          className='modal-dialog'
          role="alertdialog"
          aria-modal="true"
          aria-labelledby={titleId}
          style={{ width }}
          data-closing={isClosing || undefined}
          onAnimationEnd={handleAnimationEnd}
          onClick={(e) => e.stopPropagation()}
        >
          <div className="modal-alert-content" data-heading-only={!description || undefined}>
            <div className="modal-header-title-row">
              {IconComp && (
                <span className="modal-header-icon" aria-hidden="true">
                  <IconComp width={25} height={25} />
                </span>
              )}
              <h2 id={titleId} className="modal-title">{title}</h2>
            </div>
            {description && <div className="modal-description">{description}</div>}
          </div>
          <div className="modal-footer">
            {!singleBtn && (
              <Button variant="default" onClick={handleCancel}>{cancelLabel}</Button>
            )}
            <Button variant={btnVariant} onClick={onSave} loading={saveLoading}>
              {actionLabel}
            </Button>
          </div>
        </div>
      </div>,
      document.body
    );
  }

  return createPortal(
    <div className='modal-backdrop'>
      <div
        ref={dialogRef}
        className={`modal-dialog${className ? ` ${className}` : ''}`}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        style={{ width }}
        data-closing={isClosing || undefined}
        onAnimationEnd={handleAnimationEnd}
        onClick={(e) => e.stopPropagation()}
      >
        {/* ── Header ───────────────────────────────────────────────────── */}
        <div className='modal-header'>
          <div className='modal-header-title-row'>
            {headerStart}
            {headerIcon && (
              <span className='modal-header-icon' aria-hidden="true">
                {headerIcon}
              </span>
            )}
            <h2 id={titleId} className='modal-title'>
              {title}
            </h2>
            {headerActions}
            {showClose && <button type="button" className="modal-close" aria-label={closeLabel} onClick={onClose}>
              <CloseIcon width={closeIconSize.width} height={closeIconSize.height} aria-hidden="true" />
            </button>}
          </div>
          {description && (
            <p className='modal-description'>{description}</p>
          )}
        </div>

        {/* ── Body ─────────────────────────────────────────────────────── */}
        <div ref={bodyRef} className='modal-body'>
          {children}
        </div>

        {/* ── Footer area (note + buttons) ─────────────────────────────── */}
        {showFooter && <div className='modal-footer-area' data-shadow={isBodyScrollable || undefined}>
          {footerNote && (
            <div className='modal-footer-note'>
              {footerNote}
            </div>
          )}
          <div className='modal-footer'>
            {footerStart && <div className="modal-footer-start">{footerStart}</div>}
            <Button variant="default" onClick={handleCancel}>
              {cancelLabel}
            </Button>
            <Button variant="primary" onClick={onSave} loading={saveLoading}>
              {saveLabel}
            </Button>
          </div>
        </div>}
      </div>
    </div>,
    document.body
  );
}

